// Daftar kanonis 9 artikel regulasi Knowledge Base (PR #49, 16/11/2026).
// Isi diringkas SETIA dari 9 dokumen PDF yang diunggah pengguna (lihat
// ~/workspace/user/files/) — nomor regulasi dan isi TIDAK dikarang.
// Dipakai dua tempat: seed mode contoh (seedNyata.ts) dan aksi seed
// satu-kali mode live (seedArtikelKBRegulasi di App.tsx, idempotent).
// Isi artikel Bahasa Indonesia (konten regulasi adalah data, bukan string
// UI — UI tetap Inggris). Tiap artikel: ringkasan + ketentuan pokok
// (dengan rujukan pasal bila terbaca) + relevansi untuk kerja sama PNBP.
// Bagian "Catatan keterbatasan" pada artikel hasil pindai menyatakan jujur
// halaman mana saja yang diperiksa.

import type { ArtikelKB } from './types';
import { DOKUMEN_REGULASI, urlDokumenRegulasi } from './dokumenRegulasi';

const OLEH = 'Operator Layanan & Pengembangan Usaha';
const PADA = '2026-11-16';

/**
 * Tautan berkas PDF satu regulasi, dari daftar kanonis dokumen (PR #50).
 * Dipakai di bawah saat mengekspor ARTIKEL_REGULASI — tiap artikel
 * membawa tautan unduhnya sendiri (`tautan`).
 */
function tautanDokumen(judul: string): string | undefined {
  const d = DOKUMEN_REGULASI.find((x) => x.judul === judul);
  return d ? urlDokumenRegulasi(d.berkas) : undefined;
}

/** 9 regulasi terverifikasi — judul = nama regulasi, kategori 'Regulasi'. */
